fn swap(pair: (Int, Int)) -> (Int, Int) {
  return (pair.1, pair.0);
}

fn point_add(a: (Float64, Float64), b: (Float64, Float64)) -> (Float64, Float64) {
  return (a.0 + b.0, a.1 + b.1);
}

fn main() -> Int {
  let (a, b) = swap((1, 2));
  return a + b;
}
